const { env } = await import('node:process');
if (!env['TEXT']) { throw new Error('Missing required input: text'); }
globalThis.text = env['TEXT'];
globalThis.options = {};

const mod = await import('qrcode');
const fn = mod.default || mod;
const dataUrl = await fn.toDataURL(globalThis.text);
globalThis.result = dataUrl;
